using System;using System.Linq;using System.Reflection;using System.Threading.Tasks;using UnityEngine;using AntColony.Units;using AntColony.Buildings;using AntColony.Core;using AntColony.Data;
public static class Final1113BedProbe {
 public static async Task<string> Run(){var c=CommanderRoster.Instance.Commanders.First(x=>x&&x.IsColonyMember);c.CommandStop();AntColony.UI.SimulationPause.UserSpeed(0);var player=c.GetComponent<MeshyNativeMotionPlayer>();player.PreviewMotion="Sleep_Normally";player.PreviewPhase=.5f;
 var template=(GameObject)typeof(BuildingPlacementController).GetMethod("GetTemplate",BindingFlags.Static|BindingFlags.NonPublic).Invoke(null,new object[]{BuildingKind.Infirmary,UnitRole.Worker});var go=UnityEngine.Object.Instantiate(template,c.Position+Vector3.right*4+Vector3.up,Quaternion.identity);go.name="Final bed probe";go.SetActive(true);FacilityVisual.Attach(go.GetComponent<Infirmary>());await Task.Delay(350);
 var cam=Camera.main;UnityEngine.Object.FindAnyObjectByType<AntColony.Camera.IsometricCameraController>().enabled=false;cam.orthographicSize=3;cam.transform.position=go.transform.position+new Vector3(0,9,-.01f);cam.transform.LookAt(go.transform.position);ScreenCapture.CaptureScreenshot("work/final-motion-1113/bed-top.png");await Task.Delay(300);
 var head=player.NativeModel.GetComponentsInChildren<Transform>().First(t=>t.name=="mixamorig:Head");var feet=player.NativeModel.GetComponentsInChildren<Transform>().Where(t=>t.name=="mixamorig:LeftFoot"||t.name=="mixamorig:RightFoot").Select(t=>t.position).Aggregate((a,b)=>a+b)/2;var skins=player.NativeModel.GetComponentsInChildren<SkinnedMeshRenderer>().Where(s=>s.enabled);var b=new Bounds(head.position,Vector3.zero);var mesh=new Mesh();foreach(var s in skins){s.BakeMesh(mesh);foreach(var v in mesh.vertices)b.Encapsulate(s.transform.TransformPoint(v));}UnityEngine.Object.Destroy(mesh);
 var result="bed "+go.transform.position+" model "+go.GetComponent<FacilityVisual>().Model.name+" sleep bounds="+b+" pivot="+player.NativeModel.parent.position+" head="+head.position+" feet="+feet+" originalRotation="+c.transform.Find("Kemono").rotation.eulerAngles;System.IO.File.WriteAllText("work/final-motion-1113/bed-probe.txt",result);return result;}
}
